#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Permittivity::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            Permittivity::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in PermittivityUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Permittivity::from_base(0.0).auto_unit().unit,
        PermittivityUnit::FaradPerMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "F/m".parse::<PermittivityUnit>(),
        Ok(PermittivityUnit::FaradPerMeter)
    );
    assert_eq!(
        format!("2.5 {}", "F/m").parse::<Permittivity>(),
        Ok(Permittivity::new(2.5, PermittivityUnit::FaradPerMeter))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Permittivity>(),
        Err(ParseError::UnknownUnit)
    );
}

